void FAnimMontageInstance::Advance(float DeltaTime, struct FRootMotionMovementParams* OutRootMotionParams, bool bBlendRootMotion)
{
    SCOPE_CYCLE_COUNTER(STAT_AnimMontageInstance_Advance);	FScopeCycleCounterUObject MontageScope(Montage);
    if (IsValid())
    {
        // with custom curves, we can't just filter by weight
        // also if you have custom curve with longer 0, you'll likely to pause montage during that blending time
        // I think that is a bug. It still should move, the weight might come back later.
        if (bPlaying)
        {
            // ... skip ...
        }
+       else
+       {
+           HandleEvents(Position, Position, nullptr);
+       }
     }
}

MontageInstance->MontageSync_PostUpdate();
if(RootMotionParams != nullptr && !AnimInstanceProxy->Sync.GetUngroupedActivePlayersRead().IsEmpty())
{
   FAnimTickRecord TickRecord = AnimInstanceProxy->Sync.GetUngroupedActivePlayersRead()[0];
   if (TickRecord.MirrorDataTable)
   {
      FTransform InTransform = RootMotionParams->GetRootMotionTransform();
      if (bUsingBlendedRootMotion && !RootMotionBlendQueue.IsEmpty())
      {
         InTransform = RootMotionBlendQueue.Last().Transform;
      }
      FVector T = InTransform.GetTranslation();
      T = FAnimationRuntime::MirrorVector(T, TickRecord.MirrorDataTable->MirrorAxis);
      FQuat Q = InTransform.GetRotation();
      Q = FAnimationRuntime::MirrorQuat(Q, TickRecord.MirrorDataTable->MirrorAxis);
      FVector S = InTransform.GetScale3D();
      FTransform MirroredTransform = FTransform(Q, T, S);
      if (bUsingBlendedRootMotion && !RootMotionBlendQueue.IsEmpty())
      {
         // Defer blending in our root motion until after we get our slot weight updated
         FQueuedRootMotionBlend& LastQueuedRootMotionBlend = RootMotionBlendQueue.Last();
         LastQueuedRootMotionBlend.Transform = MirroredTransform;
      }
      else
      {
         RootMotionParams->Set(MirroredTransform);
      }
   }
}
